// SPDX-License-Identifier: MIT
// QR decode against the golden pairing payload on disk (lessons §4: read the
// shared fixture, do not hand-copy it into Kotlin). The image is generated by
// ZXing's own encoder and decoded by the production luminance half of
// `PcQrScanner`; no camera or device is involved.
package com.phonedsh.probe.pc

import com.google.zxing.BarcodeFormat
import com.google.zxing.qrcode.QRCodeWriter
import com.phonedsh.pclink.PclinkQrCode
import java.io.File
import org.json.JSONObject
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNotNull
import org.junit.Assert.assertNull
import org.junit.Test

class PcQrScannerTest {
    private fun goldenQrUri(): String {
        val root = File(System.getProperty("pdsh.repo.root") ?: ".").absoluteFile
        val vectors = File(root, "spec/pclink/v1/golden/pclink-v1-vectors.json")
        val json = JSONObject(vectors.readText(Charsets.UTF_8))
        return json.getJSONObject("pairing").getJSONObject("qr").getString("uri")
    }

    private fun qrLuminance(uri: String, size: Int = 512): Triple<ByteArray, Int, Int> {
        val matrix = QRCodeWriter().encode(uri, BarcodeFormat.QR_CODE, size, size)
        val luminance = ByteArray(matrix.width * matrix.height)
        for (row in 0 until matrix.height) {
            for (column in 0 until matrix.width) {
                // ZXing's BitMatrix true bit is a black module: 0 luminance.
                luminance[row * matrix.width + column] =
                    if (matrix.get(column, row)) 0 else 255.toByte()
            }
        }
        return Triple(luminance, matrix.width, matrix.height)
    }

    @Test
    fun `the golden pairing URI decodes from a QR image`() {
        val uri = goldenQrUri()
        val (luminance, width, height) = qrLuminance(uri)

        assertEquals(uri, PcQrScanner.decodeLuminance(luminance, width, height))
    }

    @Test
    fun `the decoded payload is the same offer the PCLink parser accepts`() {
        val uri = goldenQrUri()
        val (luminance, width, height) = qrLuminance(uri)
        val decoded = PcQrScanner.decodeLuminance(luminance, width, height)
        assertNotNull(decoded)

        val offer = PclinkQrCode.parse(decoded!!)
        assertEquals("https://relay.example", offer.relayOrigin)
        assertEquals("7gdxeackpmfrjk3ylal74yyubv", offer.pcMachineId)
        assertEquals("My PC", offer.pcName)
    }

    @Test
    fun `a blank image is no decode rather than an exception`() {
        val blank = ByteArray(64 * 64) { 255.toByte() }
        assertNull(PcQrScanner.decodeLuminance(blank, 64, 64))
    }

    @Test
    fun `a non-QR image is no decode`() {
        val noise = ByteArray(64 * 64) { (it % 251).toByte() }
        assertNull(PcQrScanner.decodeLuminance(noise, 64, 64))
    }
}
